package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class VentoyTest {
 static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static final class Disk implements BlockDevice {final RandomAccessFile file;final long sectors;int writes;boolean corrupt;Disk(File f,long sectors)throws IOException{this.sectors=sectors;file=new RandomAccessFile(f,"rw");file.setLength(sectors*512);}public int blockSize(){return 512;}public long blockCount(){return sectors;}public void read(long at,byte[] b,int n)throws IOException{file.seek(at*512);file.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{writes++;file.seek(at*512);file.write(b,0,n);if(corrupt&&at>0){file.seek(at*512);file.writeByte(b[0]^1);}}public void sync()throws IOException{file.getFD().sync();}public void close(){try{file.close();}catch(IOException e){throw new java.io.UncheckedIOException(e);}}}
 public static void main(String[] args)throws Exception {Path temp=Files.createTempDirectory("usbwb-ventoy-");try{
  VentoyBundle bundle=VentoyBundle.importPackage(new FileInputStream(".downloads/ventoy-1.1.18-linux.tar.gz"),temp.resolve("bundle").toFile(),(a,b)->{});check(bundle.version.equals("1.1.18"),"real official package import");check(bundle.file("efi.img").length()==33554432,"EFI asset size");check(VentoyBundle.load(bundle.directory).version.equals(bundle.version),"cache integrity");
  try(Disk disk=new Disk(temp.resolve("disk.img").toFile(),524288)){VentoyInstaller.install(disk,bundle,(a,b)->{});byte[] mbr=new byte[512];disk.read(0,mbr,512);long part2=VentoyInstaller.part2(disk.blockCount());check((mbr[446]&255)==128&&(mbr[450]&255)==7&&(mbr[466]&255)==239,"MBR types and active");check(OpticalImage.u32(mbr,454)==2048&&OpticalImage.u32(mbr,458)==part2-2048&&OpticalImage.u32(mbr,470)==part2&&OpticalImage.u32(mbr,474)==65536,"official partition geometry");byte[] b=new byte[512];disk.read(2048,b,512);check(new String(b,3,8,"US-ASCII").equals("EXFAT   "),"data filesystem");disk.read(part2,b,512);check(new String(b,43,11,"US-ASCII").equals("VTOYEFI    "),"EFI partition");byte[] expected=Files.readAllBytes(bundle.file("core.img").toPath()),actual=new byte[expected.length];disk.read(1,actual,actual.length);check(Arrays.equals(expected,actual),"whole core readback");expected=Files.readAllBytes(bundle.file("efi.img").toPath());actual=new byte[expected.length];disk.read(part2,actual,actual.length);check(Arrays.equals(expected,actual),"whole EFI readback");}
  try(Disk disk=new Disk(temp.resolve("update.img").toFile(),524288)){VentoyInstaller.install(disk,bundle,(a,b)->{});byte[] old=new byte[512],reserved=new byte[4096],marker=new byte[512];new Random(3).nextBytes(marker);new Random(4).nextBytes(reserved);disk.write(10000,marker,512);disk.write(2040,reserved,4096);disk.read(0,old,512);VentoyInstaller.updateMbr(disk,bundle,(a,b)->{});byte[] after=new byte[512],checkReserved=new byte[4096];disk.read(10000,after,512);check(Arrays.equals(marker,after),"update preserves data partition");disk.read(2040,checkReserved,4096);check(Arrays.equals(reserved,checkReserved),"update preserves reserved core sectors");disk.read(0,after,512);check(Arrays.equals(Arrays.copyOfRange(old,384,400),Arrays.copyOfRange(after,384,400))&&Arrays.equals(Arrays.copyOfRange(old,440,512),Arrays.copyOfRange(after,440,512)),"update preserves identity/table");long efi=VentoyInstaller.part2(disk.blockCount());disk.read(efi,after,512);after[43]^=1;disk.write(efi,after,512);int before=disk.writes;try{VentoyInstaller.updateMbr(disk,bundle,(a,b)->{});throw new AssertionError("foreign layout accepted");}catch(IOException e){check(e.getMessage().equals("VENTOY_UPDATE_LAYOUT")&&disk.writes==before,"unrecognized update zero writes");}}
  try(Disk disk=new Disk(temp.resolve("gpt.img").toFile(),524288)){VentoyInstaller.installGpt(disk,bundle,(a,b)->{});check(AdvancedDiskTools.inspectGpt(disk).contains("CRC OK"),"GPT primary/backup CRC");byte[] boot=new byte[512],core=new byte[2014*512],expected=Arrays.copyOf(Files.readAllBytes(bundle.file("core.img").toPath()),2014*512);expected[500]=0x23;disk.read(0,boot,512);disk.read(34,core,core.length);check(boot[92]==0x22&&(boot[450]&255)==238&&Arrays.equals(core,expected),"GPT boot markers and full shifted core");byte[] entries=new byte[16384];disk.read(2,entries,entries.length);check(OpticalImage.u64(entries,32)==2048&&OpticalImage.u64(entries,128+32)==VentoyInstaller.part2Gpt(disk.blockCount())&&entries[128+55]==(byte)128,"GPT geometry and EFI hidden attribute");
   byte[] first=new byte[34*512],tail=new byte[33*512];disk.read(0,first,first.length);disk.read(disk.blockCount()-33,tail,tail.length);Files.createDirectories(Paths.get("artifacts/ventoy-gpt-fixture"));Files.write(Paths.get("artifacts/ventoy-gpt-fixture/primary.bin"),first);Files.write(Paths.get("artifacts/ventoy-gpt-fixture/backup.bin"),tail);
   byte[] marker=new byte[512],reserved=new byte[4096];new Random(12).nextBytes(marker);new Random(13).nextBytes(reserved);disk.write(10000,marker,512);disk.write(2040,reserved,4096);VentoyInstaller.updateGpt(disk,bundle,(a,b)->{});byte[] actual=new byte[512],now=new byte[4096];disk.read(10000,actual,512);check(Arrays.equals(marker,actual),"GPT update preserves data");disk.read(2040,now,now.length);check(Arrays.equals(reserved,now),"GPT update preserves8reserved sectors");byte[] afterFirst=new byte[first.length],afterTail=new byte[tail.length];disk.read(0,afterFirst,afterFirst.length);disk.read(disk.blockCount()-33,afterTail,afterTail.length);check(Arrays.equals(first,afterFirst)&&Arrays.equals(tail,afterTail),"GPT update preserves whole table/identities");
   afterTail[16]^=1;disk.write(disk.blockCount()-33,afterTail,afterTail.length);int before=disk.writes;try{VentoyInstaller.updateGpt(disk,bundle,(a,b)->{});throw new AssertionError("badGPT accepted");}catch(IOException e){check(disk.writes==before,"badbackupGPT zero update writes");}
  }
  try(Disk broken=new Disk(temp.resolve("gpt-broken.img").toFile(),524288)){broken.corrupt=true;try{VentoyInstaller.installGpt(broken,bundle,(a,b)->{});throw new AssertionError("corruptGPT accepted");}catch(IOException e){byte[] boot=new byte[512];broken.read(0,boot,512);check(e.getMessage().equals("VERIFY_FAILED")&&boot[510]==0,"GPT failed write no MBR commit");}}
  try(Disk small=new Disk(temp.resolve("small.img").toFile(),131072)){try{VentoyInstaller.install(small,bundle,(a,b)->{});throw new AssertionError("small accepted");}catch(IOException e){check(e.getMessage().equals("VENTOY_SIZE")&&small.writes==0,"invalid size no writes");}}
  try(Disk broken=new Disk(temp.resolve("broken.img").toFile(),524288)){broken.corrupt=true;try{VentoyInstaller.install(broken,bundle,(a,b)->{});throw new AssertionError("corrupt accepted");}catch(IOException e){byte[] mbr=new byte[512];broken.read(0,mbr,512);check(e.getMessage().equals("VERIFY_FAILED")&&mbr[510]==0,"corruption never commits table");}}
  try(RandomAccessFile core=new RandomAccessFile(bundle.file("core.img"),"rw")){core.seek(5);core.writeByte(123);}try(Disk disk=new Disk(temp.resolve("tamper.img").toFile(),524288)){try{VentoyInstaller.install(disk,bundle,(a,b)->{});throw new AssertionError("tamper accepted");}catch(IOException e){check(e.getMessage().equals("VENTOY_ASSET_CHANGED")&&disk.writes==0,"tampered asset no writes");}}
  System.out.println("PASS: "+checks+" real Ventoy package/import/FAT16, MBR install, complete asset readback and failure-safety checks; no hardware boot claim");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(temp)){paths.sorted(Comparator.reverseOrder()).forEach(path->{try{Files.delete(path);}catch(IOException ignored){}});}}}
}
